def mru_cache(maxsize=128, typed=False):

    class Cache:
        """A MRU cache that saves up to `maxsize` results based on a Most
        Recently Used (MRU) algorithm.

        Args:
            maxsize: The maximum number of results to store in the cache.
            typed: A boolean indicating whether the cached function returns
                typed or untyped results.

        Attributes:
            _cache: A dictionary of {Key: Value} pairs, where Key is the
                input arguments to the function and Value is the result
                returned by the function.
            _lru: A dictionary of {Key: datetime.datetime} pairs, where Key
                is the input arguments to the function and Value is the
                datetime object when the result was last accessed.
        """

        def __init__(self, maxsize=128, typed=False):
            self._cache = {}
            self._lru = {}
            self.maxsize = maxsize
            self.typed = typed

        def __call__(self, func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = self.make_key(args, kwargs)
                if key in self._cache and func is not None:
                    self._move_to_front(key)
                    return self._cache[key]
                else:
                    result = func(*args, **kwargs)
                    self._cache[key] = result
                    self._lru[key] = datetime.datetime.now()
                    if len(self._cache) > self.maxsize:
                        self._trim_cache()
                    return result
            return wrapper

        def make_key(self, args, kwargs):
            """Creates a key for the cache based on the input arguments.

            Args:
                args: The positional arguments to the function.
                kwargs: The keyword arguments to the function.

            Returns:
                A hashable object that can be used as a key in the cache.
            """
            if self.typed:
                return (args, tuple(kwargs.items()))
            else:
                return (args, frozenset(kwargs.items()))

        def _move_to_front(self, key):
            """Moves a key to the front of the LRU list.

            Args:
                key: The key to move to the front.
            """
            if key in self._lru:
                del self._lru[key]
                self._lru[key] = datetime.datetime.now()

        def _trim_cache(self):
            """Trims the cache to the specified size."""
            for key in self._lru:
                if key not in self._cache:
                    del self._lru[key]
                    break
            self._cache = {k: v for k, v in self._cache.items() if k in self._lru}

    return Cache(maxsize=maxsize, typed=typed)

def lru_cache(maxsize=128, typed=False):
    # Decorator to wrap a function with a memoizing callable that saves up to `maxsize` results based on a Least Recently Used (LRU) algorithm.

    class LRUCache(object):
        def __init__(self, maxsize):
            self.maxsize = maxsize
            self.cache = OrderedDict()

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                key = (args, frozenset(kwargs))
                if key in self.cache:
                    # Get the value from cache if it exists
                    value = self.cache[key]
                else:
                    # If not, call the function and add the result to the cache
                    value = func(*args, **kwargs)
                    self.cache[key] = value

                # Check if the cache is full and remove the least recently used item if it is
                if len(self.cache) == self.maxsize:
                    self.cache.popitem(last=False)

                return value

            return wrapper

    return LRUCache(maxsize)

