def lfu_cache(maxsize=128, typed=False):
    def decorator(f):
        cache = {}
        freq = {}
        hits = {}

        def wrapper(*args, **kwargs):
            key = args + tuple(kwargs.items())
            if key not in cache:
                cache[key] = f(*args, **kwargs)
                freq[key] = 1
            else:
                freq[key] += 1
            hits[key] = hits.get(key, 0) + 1
            if len(hits) > maxsize:
                # remove the least frequently used item
                lfu = min(hits, key=hits.get)
                if lfu in cache:
                    del cache[lfu]
                    del freq[lfu]
            return cache[key]
        return wrapper
    return decorator
